// Parse and normalize incoming request
// Detect Open WebUI system prompts (auto-tagging, follow-ups, title generation)
const input = $json.body || $json;

// Check multiple possible field names for user input
// Open WebUI may send as chatInput, projectSlug, message, or query
const chatInput = input.chatInput || input.message || input.query || input.projectSlug || '';
const requirements = input.requirements || '';

// Detect Open WebUI system prompts
const isAutoTag = chatInput.includes('### Task:') && chatInput.includes('Generate 1-3 broad tags');
const isFollowUp = chatInput.includes('### Task:') && chatInput.includes('Suggest 3-5 relevant follow-up');
const isTitleGen = chatInput.includes('### Task:') && chatInput.includes('Generate a concise');
const isSystemPrompt = isAutoTag || isFollowUp || isTitleGen;

// Also check requirements field for system prompts
const reqIsAutoTag = requirements.includes('### Task:') && requirements.includes('Generate 1-3 broad tags');
const reqIsFollowUp = requirements.includes('### Task:') && requirements.includes('Suggest 3-5 relevant follow-up');
const reqIsTitleGen = requirements.includes('### Task:') && requirements.includes('Generate a concise');
const reqIsSystemPrompt = reqIsAutoTag || reqIsFollowUp || reqIsTitleGen;

// Determine system prompt type
let systemPromptType = null;
if (isAutoTag || reqIsAutoTag) systemPromptType = 'auto-tag';
else if (isFollowUp || reqIsFollowUp) systemPromptType = 'follow-up';
else if (isTitleGen || reqIsTitleGen) systemPromptType = 'title-gen';

// Only use projectSlug from input if it looks like a slug (no spaces, short)
// Otherwise it might be the user message sent with wrong field name
const inputProjectSlug = input.projectSlug || null;
const looksLikeSlug = inputProjectSlug && inputProjectSlug.length < 100 && !inputProjectSlug.includes(' ');
const actualProjectSlug = looksLikeSlug ? inputProjectSlug : null;

// FIX: Use requirements as fallback for rawInput when not a system prompt
// This handles Open WebUI sending user messages in the requirements field
let rawInput = chatInput;
if (!rawInput && !(isSystemPrompt || reqIsSystemPrompt) && requirements) {
  rawInput = requirements;
}

return [{ json: {
  rawInput: rawInput,
  projectSlug: actualProjectSlug,
  projectName: input.projectName || null,
  requirements: input.requirements || null,
  sessionId: input.sessionId || null,
  isSystemPrompt: isSystemPrompt || reqIsSystemPrompt,
  systemPromptType: systemPromptType
} }];

const type = $input.first().json.systemPromptType;
let response = {};
if (type === 'auto-tag') { response = { tags: ['project-management', 'architecture'] }; }
else if (type === 'follow-up') { response = { questions: ['What specific aspects would you like to explore?'] }; }
else if (type === 'title-gen') { response = { title: 'Project Manager Assistant' }; }
return [{ json: response }];

