const raw = $json.message?.content;
let parsed;
try { parsed = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (e) { return [{ json: { valid: false, errors: ['PRD parse failed: ' + e.message], prdMarkdown: '' } }]; }
const md = String(parsed?.markdown || '');
const errors = [];
if (!md.startsWith('# PRD:')) errors.push('First line must start with "# PRD:"');
const fnv1a = (s) => { let h = 0x811c9dc5; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = (h * 0x01000193) >>> 0; } return ('0000000' + h.toString(16)).slice(-8); };
return [{ json: { valid: errors.length === 0, errors, prdMarkdown: md, prdHash: fnv1a(md) } }];

// Build Git Script - prepares data for docker exec git operations
const ctx = $('Pass Context').first().json;
const prdMd = $('Validate PRD').first().json.prdMarkdown;
const jobId = ctx.jobId;
const projectSlug = ctx.projectSlug;

// Use shared volume accessible to both n8n and taskmaster
const repoDir = '/data/shared/software-delivery';
const projectDir = repoDir + '/' + projectSlug + '-docs';
const remote = 'git@github.com:shlapolosa/software-delivery.git';

return [{ json: { ...ctx, repoDir, projectDir, remote, prdMarkdown: prdMd } }];

const ctx = $('Build Git Script').first().json;
const prdMd = ctx.prdMarkdown;
const base64Content = Buffer.from(prdMd).toString('base64');
return [{ json: { ...ctx, prdBase64: base64Content } }];

// Build Taskmaster execution script - uses shared volume accessible to both n8n and taskmaster
const ctx = $('Pass Context').first().json;
const projectSlug = ctx.projectSlug;
const jobId = ctx.jobId;
const artifacts = $('Build Capability Tree').first().json.artifacts || {};
const prdMarkdown = $('Validate PRD').first().json.prdMarkdown || '';

// Path in shared volume (mounted as /data/shared in n8n and taskmaster)
const sharedDir = `/data/shared/taskmaster/${projectSlug}`;

return [{ json: { ...ctx, sharedDir, prdMarkdown, artifacts } }];

const ctx = $json;
const prdMd = ctx.prdMarkdown;
const base64Content = Buffer.from(prdMd).toString('base64');
return [{ json: { ...ctx, prdBase64: base64Content } }];

// Parse Taskmaster output from executeCommand
const ctx = $('Build Taskmaster Script').first().json;
const cmdOutput = $json.stdout || '';

let tasks = { tasks: [] };
try {
  tasks = JSON.parse(cmdOutput.trim());
} catch (e) {
  console.log('Failed to parse tasks.json:', e.message);
}

return [{ json: { ...ctx, taskmasterTasks: tasks, taskmasterSuccess: tasks.tasks.length > 0 } }];

// Build ADO Stories from Taskmaster tasks and enriched sequences
const ctx = $input.first().json;
const tasks = (ctx.taskmasterTasks && ctx.taskmasterTasks.tasks) || [];
const enrichedSeq = (ctx.artifacts && ctx.artifacts.enriched_sequences) || {};
const sequences = enrichedSeq.enrichedSequences || [];

// Complexity to story points mapping
const toStoryPoints = (complexity) => {
  if (!complexity || complexity <= 3) return 3;
  if (complexity <= 5) return 5;
  if (complexity <= 7) return 8;
  return 13;
};

// Priority to ADO priority mapping
const toAdoPriority = (p) => {
  const map = { 'Critical': 1, 'High': 2, 'Medium': 3, 'Low': 4 };
  return map[p] || 3;
};

const workItems = [];

// Create Epics from use cases
for (const seq of sequences) {
  workItems.push({
    type: 'Epic',
    title: `${seq.useCaseId}: ${seq.useCaseName}`,
    description: `Implementation of use case: ${seq.useCaseName}`,
    tags: ['auto-generated', ctx.projectSlug],
    areaPath: ctx.projectSlug,
    tempId: seq.useCaseId
  });
}

// Create Features from flow steps that need work
for (const seq of sequences) {
  for (const step of seq.enrichedFlow || []) {
    if (step.componentStatus !== 'exists' && step.ticket) {
      workItems.push({
        type: 'Feature',
        title: step.ticket.title || step.action,
        description: `From: ${(step.from && step.from.component) || 'Source'} → To: ${(step.to && step.to.component) || 'Target'}\n\nAction: ${step.action}`,
        priority: toAdoPriority(step.ticket.priority),
        parentTempId: seq.useCaseId,
        tags: ['auto-generated', step.componentStatus]
      });
    }
  }
}

// Create User Stories from Taskmaster tasks
for (const task of tasks) {
  workItems.push({
    type: 'User Story',
    title: task.title,
    description: task.description + '\n\n**Details:**\n' + (task.details || ''),
    storyPoints: toStoryPoints(task.complexityScore),
    acceptanceCriteria: task.testStrategy || '',
    priority: task.priority === 'high' ? 2 : (task.priority === 'low' ? 4 : 3),
    tags: ['taskmaster', ...(task.tags || [])]
  });

  // Create Tasks from subtasks
  for (const sub of task.subtasks || []) {
    workItems.push({
      type: 'Task',
      title: sub.title,
      description: sub.description,
      remainingWork: toStoryPoints(sub.complexityScore),
      parentTaskId: task.id
    });
  }
}

return [{ json: { ...ctx, adoWorkItems: workItems, workItemCount: workItems.length } }];

// Collect created work item IDs
const items = $input.all();
const createdIds = items.map(i => ({
  tempId: i.json.tempId,
  adoId: i.json.id,
  title: i.json.fields?.['System.Title'] || i.json.title,
  type: i.json.fields?.['System.WorkItemType'] || i.json.type
}));
return [{ json: { createdWorkItems: createdIds, count: createdIds.length } }];

// Prepare Taskmaster artifact for storage
const ctx = $('Parse Taskmaster Output').first().json;
const adoResults = $json.createdWorkItems || [];
const tasks = ctx.taskmasterTasks || { tasks: [] };

// Calculate hash for deduplication
const fnv1a = (s) => { let h = 0x811c9dc5; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = (h * 0x01000193) >>> 0; } return ('0000000' + h.toString(16)).slice(-8); };
const tasksHash = fnv1a(JSON.stringify(tasks));

return [{ json: { 
  projectId: ctx.projectId,
  jobId: ctx.jobId,
  projectSlug: ctx.projectSlug,
  taskmasterTasks: tasks,
  tasksHash,
  adoWorkItems: adoResults,
  taskmasterSuccess: ctx.taskmasterSuccess || false
} }];

const ctx = $('Pass Context').first().json;

// Safely get data from nodes that may not have executed
let tmArtifact = {};
let tmTasks = { tasks: [] };
let adoStories = [];
let adoCreatedCount = 0;

try { tmArtifact = $('Store Taskmaster Artifact').first().json || {}; } catch(e) {}
try { 
  const parsed = $('Parse Taskmaster Output').first().json;
  tmTasks = (parsed && parsed.taskmasterTasks) || { tasks: [] };
} catch(e) {}
try {
  const stories = $('Build ADO Stories').first().json;
  adoStories = (stories && stories.adoWorkItems) || [];
} catch(e) {}
try {
  const collected = $('Collect Work Item IDs').first().json;
  adoCreatedCount = (collected && collected.count) || 0;
} catch(e) {}

return [{ json: { 
  success: true, 
  jobId: ctx.jobId, 
  projectSlug: ctx.projectSlug, 
  stage: 'project-management', 
  prdPath: ctx.projectSlug + '-docs/docs/PRD.md',
  taskmaster: {
    tasksCount: (tmTasks.tasks && tmTasks.tasks.length) || 0,
    artifactId: tmArtifact.id,
    artifactVersion: tmArtifact.version
  },
  ado: {
    workItemsGenerated: adoStories.length,
    workItemsCreated: adoCreatedCount
  }
} }];

// Project Manager Chat Handler
const agentConfig = {
  name: 'Project Manager',
  shortName: 'project-manager',
  collectionName: 'agent-knowledge-project-manager',
  folder: 'agent-docs/project-manager',
  helpFile: '/data/shared/knowledge/agent-docs/project-manager/help.md'
};

const input = $input.all()[0].json;
const intent = input.intent || 'help';
const query = input.query || '';

let response = {
  agent: agentConfig.name,
  intent: intent,
  success: true
};

switch (intent) {
  case 'help':
    response.content = `# ${agentConfig.name} Agent Help\n\n## Available Commands\n\n| Intent | Description |\n|--------|-------------|\n| help | Show this help message |\n| status | Check knowledge base status |\n| list | List documents in knowledge base |\n| upload | Upload a document to knowledge base |\n| reload | Reload all documents in knowledge base |\n| query | Query the knowledge base |\n\n## Knowledge Base\n- Collection: ${agentConfig.collectionName}\n- Folder: ${agentConfig.folder}\n\n## PM Domains\n- Product Requirements (PRD)\n- Sprint Planning\n- Resource Management\n- Timeline Estimation\n`;
    response.message = `${agentConfig.name} Help`;
    break;

  case 'status':
    response.action = 'query_qdrant_status';
    response.collection = agentConfig.collectionName;
    break;

  case 'list':
    response.action = 'query_qdrant_list';
    response.collection = agentConfig.collectionName;
    break;

  case 'upload':
    response.action = 'call_knowledge_loader';
    response.loaderPayload = {
      action: 'upload',
      collection: agentConfig.collectionName,
      folder: agentConfig.folder,
      content: input.content || '',
      filename: input.filename || ''
    };
    break;

  case 'reload':
    response.action = 'call_knowledge_loader';
    response.loaderPayload = {
      action: 'reload',
      collection: agentConfig.collectionName,
      folder: agentConfig.folder
    };
    break;

  case 'query':
    response.action = 'rag_query';
    response.collection = agentConfig.collectionName;
    response.query = query;
    break;

  default:
    response.success = false;
    response.errorMessage = `Unknown intent: ${intent}. Valid intents: help, status, list, upload, reload, query`;
}

return [{ json: response }];

// Build Azure DevOps push payload
const ctx = $("Build Git Script").first().json;
const repoInfo = $("Get Azure Repo Info").first().json;
const branchCheck = $json;
const projectSlug = ctx.projectSlug;
const jobId = ctx.jobId;

// Get artifact content
const artifactContent = ctx.artifactContent || ctx.artifactMarkdown || ctx.projectMgmtMarkdown || ctx.content || "";

// Include jobId in filename for uniqueness
const artifactPath = `/docs/project-management-${jobId}.md`;

// Determine branch reference
const branchName = `refs/heads/${projectSlug}`;

// Check if branch exists and get its current commit SHA
let oldObjectId = "0000000000000000000000000000000000000000";

if (branchCheck.value && branchCheck.value.length > 0) {
  oldObjectId = branchCheck.value[0].objectId;
}

// Always use 'add' for new unique filenames (with jobId)
const changeType = "add";

// Build the push payload
const changes = [{
  changeType: changeType,
  item: { path: `/${projectSlug}-docs${artifactPath}` },
  newContent: {
    content: Buffer.from(artifactContent).toString("base64"),
    contentType: "base64encoded"
  }
}];

return [{
  json: {
    ...ctx,
    azurePushPayload: {
      refUpdates: [{
        name: branchName,
        oldObjectId: oldObjectId
      }],
      commits: [{
        comment: `Add project management artifacts for ${projectSlug} (job ${jobId})`,
        changes: changes
      }]
    },
    azureRepoInfo: repoInfo,
    branchExists: branchCheck.value && branchCheck.value.length > 0
  }
}];

// Parse and normalize incoming request
// Detect Open WebUI system prompts (auto-tagging, follow-ups, title generation)
const input = $json.body || $json;

// Check multiple possible field names for user input
// Open WebUI may send as chatInput, projectSlug, message, or query
const chatInput = input.chatInput || input.message || input.query || input.projectSlug || '';
const requirements = input.requirements || '';

// Detect Open WebUI system prompts
const isAutoTag = chatInput.includes('### Task:') && chatInput.includes('Generate 1-3 broad tags');
const isFollowUp = chatInput.includes('### Task:') && chatInput.includes('Suggest 3-5 relevant follow-up');
const isTitleGen = chatInput.includes('### Task:') && chatInput.includes('Generate a concise');
const isSystemPrompt = isAutoTag || isFollowUp || isTitleGen;

// Also check requirements field for system prompts
const reqIsAutoTag = requirements.includes('### Task:') && requirements.includes('Generate 1-3 broad tags');
const reqIsFollowUp = requirements.includes('### Task:') && requirements.includes('Suggest 3-5 relevant follow-up');
const reqIsTitleGen = requirements.includes('### Task:') && requirements.includes('Generate a concise');
const reqIsSystemPrompt = reqIsAutoTag || reqIsFollowUp || reqIsTitleGen;

// Determine system prompt type
let systemPromptType = null;
if (isAutoTag || reqIsAutoTag) systemPromptType = 'auto-tag';
else if (isFollowUp || reqIsFollowUp) systemPromptType = 'follow-up';
else if (isTitleGen || reqIsTitleGen) systemPromptType = 'title-gen';

// Only use projectSlug from input if it looks like a slug (no spaces, short)
// Otherwise it might be the user message sent with wrong field name
const inputProjectSlug = input.projectSlug || null;
const looksLikeSlug = inputProjectSlug && inputProjectSlug.length < 100 && !inputProjectSlug.includes(' ');
const actualProjectSlug = looksLikeSlug ? inputProjectSlug : null;

// FIX: Use requirements as fallback for rawInput when not a system prompt
// This handles Open WebUI sending user messages in the requirements field
let rawInput = chatInput;
if (!rawInput && !(isSystemPrompt || reqIsSystemPrompt) && requirements) {
  rawInput = requirements;
}

return [{ json: {
  rawInput: rawInput,
