const response = $input.first().json;
const parsed = $('Entry: Parse Input').first().json;
let classification = { mode: 'chat', intent: 'help' };
try { const content = response.message?.content; if (content) classification = JSON.parse(content); } catch (e) {}
return [{ json: { ...parsed, mode: classification.mode || 'chat', intent: classification.intent || 'help', extractedProjectSlug: classification.projectSlug || null } }];

const input = $input.first().json;
const intent = input.intent || 'help';
const projectSlug = input.projectSlug || input.extractedProjectSlug;
let response = { agent: 'Project Manager', stage: 'project-management', intent: intent, action: 'direct_response', query: null };
switch(intent) {
  case 'help':
    response.content = '# Project Management Pipeline\\n\\n## Commands\\n| Command | Description |\\n|---------|-------------|\\n| help | Show help |\\n| status | Check job status |\\n| artifacts | List artifacts |\\n| jobs | List recent jobs |\\n| list | List projects |';
    response.message = 'Help';
    break;
  case 'status': case 'jobs':
    response.action = 'query_db';
    response.query = `SELECT j.id, p.slug as project, j.stage, j.status, j.created_at, j.completed_at FROM architecture.jobs j JOIN architecture.projects p ON j.project_id = p.id WHERE j.stage = 'project-management' ORDER BY j.created_at DESC LIMIT 10`;
    response.queryType = 'jobs';
    break;
  case 'artifacts':
    response.action = 'query_db';
    response.query = `SELECT a.id, p.slug as project, a.artifact_type, a.version, a.created_at FROM architecture.artifacts a JOIN architecture.projects p ON a.project_id = p.id WHERE a.artifact_type LIKE 'project_%' ORDER BY a.created_at DESC LIMIT 10`;
    response.queryType = 'artifacts';
    break;
  case 'list':
    response.action = 'query_db';
    response.query = 'SELECT p.id, p.slug, p.name, p.created_at FROM architecture.projects p ORDER BY p.created_at DESC LIMIT 20';
    response.queryType = 'projects';
    break;
  default:
    response.content = 'Unknown command. Try help.';
    response.message = 'Unknown';
}
return [{ json: response }];

const chatContext = $('Entry: Chat Handler').first().json;
const queryResults = $input.all().map(i => i.json);
let content = '';
const queryType = chatContext.queryType;
if (queryResults.length === 0) { content = 'No results found.'; }
else {
  switch(queryType) {
    case 'jobs':
      content = '# Jobs\\n\\n| ID | Project | Stage | Status | Created | Completed |\\n|----|---------|-------|--------|---------|-----------|\\n';
      for (const row of queryResults) { content += `| ${row.id?.substring(0,8)}... | ${row.project} | ${row.stage} | ${row.status} | ${new Date(row.created_at).toLocaleDateString()} | ${row.completed_at ? new Date(row.completed_at).toLocaleDateString() : '-'} |\\n`; }
      break;
    case 'artifacts':
      content = '# Artifacts\\n\\n| ID | Project | Type | Version | Created |\\n|----|---------|------|---------|---------|\\n';
      for (const row of queryResults) { content += `| ${row.id?.substring(0,8)}... | ${row.project} | ${row.artifact_type} | ${row.version} | ${new Date(row.created_at).toLocaleDateString()} |\\n`; }
      break;
    case 'projects':
      content = '# Projects\\n\\n| Slug | Name | Created |\\n|------|------|---------|\\n';
      for (const row of queryResults) { content += `| ${row.slug} | ${row.name} | ${new Date(row.created_at).toLocaleDateString()} |\\n`; }
      break;
    default: content = JSON.stringify(queryResults, null, 2);
  }
}
return [{ json: { agent: 'Project Manager', stage: 'project-management', intent: chatContext.intent, success: true, content: content, message: `Found ${queryResults.length} result(s)`, rowCount: queryResults.length } }];

const init = $('Initialize Parameters').first().json;
const project = $('Load Project').first().json;
const job = $json;
return [{ json: { ...init, projectId: project.id, projectSlug: project.slug, projectName: project.name || project.slug, jobId: job.id } }];

const ctx = $('Pass Context').first().json;
const rows = $input.all().map(i => i.json);
const byType = {};
for (const r of rows) byType[r.type] = r.content;
return [{ json: { ...ctx, artifacts: byType } }];

// Build Capability Tree from enriched sequences
const ctx = $json;
const enrichedSeq = ctx.artifacts?.enriched_sequences || {};
const sequences = enrichedSeq.enrichedSequences || [];

let capabilityTree = '## Capability Tree\n\n';

for (const seq of sequences) {
  const ucId = seq.useCaseId || `UC-${sequences.indexOf(seq) + 1}`;
  capabilityTree += `### Capability: ${ucId} ${seq.useCaseName || 'Unnamed'}\n`;
  capabilityTree += `Phase 0 - ${seq.useCaseName || 'Implementation'}\n\n`;

  let prevFeatureId = null;
  const flow = seq.enrichedFlow || [];
  for (let i = 0; i < flow.length; i++) {
    const step = flow[i];
    if (step.componentStatus === 'exists') continue;

    const featureId = `${ucId}.${i + 1}`;
    capabilityTree += `#### Feature: ${step.action || 'Action'}\n`;
    capabilityTree += `- **Description**: ${step.from?.component || 'Source'} → ${step.to?.component || 'Target'}: ${step.action || 'N/A'}\n`;
    capabilityTree += `- **Inputs**: Request from ${step.from?.component || 'Source'} (${step.from?.type || 'unknown'})\n`;
    capabilityTree += `- **Outputs**: Response to ${step.to?.component || 'Target'} (${step.to?.type || 'unknown'})\n`;
    capabilityTree += `- **Behavior**: ${step.action || 'N/A'}\n`;
    capabilityTree += `- **Depends on**: ${prevFeatureId ? `[${prevFeatureId}]` : 'None'}\n`;
    capabilityTree += `- **Priority**: ${step.ticket?.priority || 'Medium'}\n`;
    capabilityTree += `- **Status**: ${step.componentStatus || 'unknown'}\n\n`;

    prevFeatureId = featureId;
  }
}

return [{ json: { ...ctx, capabilityTree, hasEnrichedSequences: sequences.length > 0 } }];

